const dsl = `@startuml
title <size:24>System Context View: Library</size>

set separator none
left to right direction

<style>
  root {
    BackgroundColor: #ffffff
    FontColor: #444444
  }
</style>

!include <C4/C4>
!include <C4/C4_Context>

Person(Patron, "Patron", $descr="Borrows books at the library.", $tags="", $link="")
System(Library, "Library", $descr="Manages books and loans.", $tags="", $link="")

Rel(Patron, Library, "Browses the catalogue through", $techn="HTTPS", $tags="", $link="")

SHOW_LEGEND(true)
hide stereotypes
@enduml`;

// --- PlantUML text encoding: raw deflate (stored blocks) + custom base64 ---
function deflateStored(data) {
  const out = [];
  const chunk = 65535;
  for (let off = 0; off < data.length; off += chunk) {
    const slice = data.subarray(off, Math.min(off + chunk, data.length));
    out.push(off + chunk >= data.length ? 1 : 0); // BFINAL, BTYPE=00 (stored)
    const len = slice.length;
    out.push(len & 0xff, (len >> 8) & 0xff);
    const nlen = (~len) & 0xffff;
    out.push(nlen & 0xff, (nlen >> 8) & 0xff);
    for (let i = 0; i < len; i++) out.push(slice[i]);
  }
  return new Uint8Array(out);
}

const DIGEST = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz-_";
function plantumlBase64(bytes) {
  let sb = "";
  let i = 0;
  while (i < bytes.length) {
    const b0 = bytes[i++] & 0xff;
    if (i === bytes.length) {
      sb += DIGEST[b0 >> 2] + DIGEST[(b0 & 0x3) << 4];
      break;
    }
    const b1 = bytes[i++] & 0xff;
    if (i === bytes.length) {
      sb += DIGEST[b0 >> 2] + DIGEST[((b0 & 0x3) << 4) | ((b1 & 0xF0) >> 4)] + DIGEST[(b1 & 0xF) << 2];
      break;
    }
    const b2 = bytes[i++] & 0xff;
    sb += DIGEST[b0 >> 2] + DIGEST[((b0 & 0x3) << 4) | ((b1 & 0xF0) >> 4)] + DIGEST[((b1 & 0xF) << 2) | ((b2 & 0xC0) >> 6)] + DIGEST[b2 & 0x3F];
  }
  return sb;
}

function utf8(text) {
  if (typeof TextEncoder !== "undefined") return new TextEncoder().encode(text);
  const out = [];
  for (const ch of text) {
    const cp = ch.codePointAt(0);
    if (cp < 0x80) out.push(cp);
    else if (cp < 0x800) out.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
    else if (cp < 0x10000) out.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
    else out.push(0xf0 | (cp >> 18), 0x80 | ((cp >> 12) & 0x3f), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
  }
  return new Uint8Array(out);
}

const encoded = plantumlBase64(deflateStored(utf8(dsl)));
const url = "https://www.plantuml.com/plantuml/png/" + encoded;

let res;
try {
  res = await fetch(url);
} catch (e) {
  return { error: "fetch failed: " + String(e), url };
}

const buf = new Uint8Array(await res.arrayBuffer());
const isPng = buf.length > 8 && buf[0] === 0x89 && buf[1] === 0x50 && buf[2] === 0x4e && buf[3] === 0x47;
let b64 = "";
if (isPng) {
  let bin = "";
  for (let i = 0; i < buf.length; i++) bin += String.fromCharCode(buf[i]);
  b64 = btoa(bin);
}
return { status: res.status, contentType: res.headers.get("content-type"), size: buf.length, isPng, url, b64: isPng ? b64 : null, head: isPng ? null : Buffer ? null : Array.from(buf.slice(0, 200)).map(b => String.fromCharCode(b)).join("") };

